M = 61
count = 0
for a in range(1, M + 1):
    for b in range(1, M + 1):
        for c in range(1, M + 1):
            for d in range(1, M + 1):
                # We need to check if a^2 + b^2 + c^3 - d^3 is a multiple of 61
                expression = a**2 + b**2 + c**3 - d**3
                if expression % M == 0:
                    count += 1

print(count)
